#include <chrono>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// Common PolyBench-style definitions (DATA_TYPE, etc.)
#include "defines.hpp"

// Benchmark-specific definitions (N, TSTEPS, etc.)
#include "adi.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 *
 * We implement this via a Halide Func and schedule it to use
 * vectorization over the inner (x == j) dimension and parallelism
 * over the outer (y == i) dimension for good locality and throughput.
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple machine-width-based vectorization factor:
    const int vec_width = std::max(1, 32 / int(sizeof(num_t)));

    // Row-major in x; parallelize rows (y) and vectorize x.
    init_u
        .parallel(y)
        .vectorize(x, vec_width);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * The ADI scheme consists of:
 *   - a "column sweep" that computes v and intermediate p, q from u, and
 *   - a "row sweep" that computes new u and p, q from v.
 *
 * Each sweep contains 1D tridiagonal solves (Thomas algorithm) along one
 * spatial dimension; those solves are inherently sequential along that
 * line. Halide does not natively represent such loop-carried recurrences
 * within a single Func (because self-references must use the same
 * coordinates), so we keep the recurrences in C++ loops, but we factor
 * out the purely stencil-like work into Halide pipelines for better
 * locality and vectorization.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // --------------------------------------------------------------------
    // Scalar parameters (identical to original code)
    // --------------------------------------------------------------------
    num_t DX   = num_t(1.0) / num_t(n);
    num_t DY   = num_t(1.0) / num_t(n);
    num_t DT   = num_t(1.0) / num_t(tsteps);
    num_t B1   = num_t(2.0);
    num_t B2   = num_t(1.0);
    num_t mul1 = B1 * DT / (DX * DX);
    num_t mul2 = B2 * DT / (DY * DY);

    num_t a = -mul1 / num_t(2.0);
    num_t b = num_t(1.0) + mul1;
    num_t c = a;
    num_t d = -mul2 / num_t(2.0);
    num_t e = num_t(1.0) + mul2;
    num_t f = d;

    const num_t one  = num_t(1.0);
    const num_t two  = num_t(2.0);
    const num_t one_plus_2d = one + two * d; // 1 + 2*d
    const num_t one_plus_2a = one + two * a; // 1 + 2*a

    // --------------------------------------------------------------------
    // Halide pipelines for stencil-like precomputations
    // --------------------------------------------------------------------
    //
    // Coordinates: x == j (fast / contiguous), y == i (slow).
    Var x("x"), y("y");

    // Wrap u and v as Halide Funcs so we can attach boundary conditions
    // and build derivative-like stencils around them.
    Func u_func("u_func"), v_func("v_func");
    u_func(x, y) = u(x, y);
    v_func(x, y) = v(x, y);

    using Halide::BoundaryConditions::repeat_edge;

    // Clamp to edges so that stencil accesses at y-1 / y+1 are always
    // within bounds. This makes Halide's bounds inference happy and
    // avoids any out-of-bounds reads, even though we only *use* the
    // interior region [1, n-2] in the numerical scheme.
    Func u_clamped("u_clamped"), v_clamped("v_clamped");
    u_clamped(x, y) = repeat_edge(u_func)(x, y);
    v_clamped(x, y) = repeat_edge(v_func)(x, y);

    // Precompute the u-dependent part of the RHS used in the column sweep.
    // Original inner expression (for 1 <= i,j <= n-2):
    //
    //   num = -d * u[i-1][j]
    //         + (1 + 2*d) * u[i][j]
    //         - f * u[i+1][j]
    //         - a * q[i][j-1];
    //
    // C indices map as u[i][j] -> u(j, i), so the stencil along i
    // corresponds to y-1, y, y+1 in Halide coordinates.
    //
    // We factor this as:
    //   base_col(i,j) = -d*u[i-1][j] + (1 + 2*d)*u[i][j] - f*u[i+1][j]
    //   num           = base_col(i,j) - a*q[i][j-1];
    //
    // and compute base_col(i,j) via Halide across the whole grid.
    Func col_rhs("col_rhs");
    col_rhs(x, y) =
        -d * u_clamped(x, y - 1) +
        one_plus_2d * u_clamped(x, y) -
        f * u_clamped(x, y + 1);

    // Similarly, precompute the v-dependent part of the RHS for the row sweep.
    //
    // Original inner expression (for 1 <= i,j <= n-2):
    //
    //   num = -a * v[i-1][j]
    //         + (1 + 2*a) * v[i][j]
    //         - c * v[i+1][j]
    //         - d * q[i][j-1];
    //
    // v[i][j] -> v(j, i) so again this is a vertical stencil in y.
    //
    //   base_row(i,j) = -a*v[i-1][j] + (1 + 2*a)*v[i][j] - c*v[i+1][j]
    //   num           = base_row(i,j) - d*q[i][j-1];
    //
    Func row_rhs("row_rhs");
    row_rhs(x, y) =
        -a * v_clamped(x, y - 1) +
        one_plus_2a * v_clamped(x, y) -
        c * v_clamped(x, y + 1);

    // Schedule for stencil pipelines: parallelize over rows (y) and
    // vectorize over contiguous x (j).
    const int vec_width = std::max(1, 32 / int(sizeof(num_t)));

    col_rhs
        .parallel(y)
        .vectorize(x, vec_width);

    row_rhs
        .parallel(y)
        .vectorize(x, vec_width);

    // Scratch buffers for the stencil results. We reuse them across
    // time steps to avoid repeated allocation.
    Halide::Buffer<num_t, 2> col_rhs_buf(n, n);
    Halide::Buffer<num_t, 2> row_rhs_buf(n, n);

    // --------------------------------------------------------------------
    // Time-stepping loop (sequential in t, as in the original code)
    // --------------------------------------------------------------------
    for (int t = 1; t <= tsteps; t++) {

        // ================================================================
        // Column sweep: compute v (and p, q) from current u
        // ================================================================

        // Compute the u-dependent part of the RHS for all (j, i).
        // This is the data-parallel portion and runs via Halide with
        // good cache behavior and SIMD usage.
        col_rhs.realize(col_rhs_buf);

        // Remaining work is the tridiagonal solves along each column
        // (Thomas algorithm), which are inherently sequential along j.
        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // denom = a * p[i][j-1] + b;
                num_t denom = a * p(j - 1, i) + b;

                // p[i][j] = -c / denom;
                p(j, i) = -c / denom;

                // Use precomputed base_col(i,j) instead of recomputing
                // the three-point stencil from u each iteration.
                //
                // num =
                //    (-d * u[i-1][j] + (1 + 2*d) * u[i][j] - f * u[i+1][j])
                //    - a * q[i][j-1];
                num_t base_col = col_rhs_buf(j, i); // j == x, i == y
                num_t num      = base_col - a * q(j - 1, i);

                // q[i][j] = num / denom;
                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = one;

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ================================================================
        // Row sweep: compute new u (and p, q) from current v
        // ================================================================

        // Compute the v-dependent part of the RHS for all (j, i).
        // Again, this is a pure stencil and benefits from Halide
        // parallelization and vectorization.
        row_rhs.realize(row_rhs_buf);

        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // denom = d * p[i][j-1] + e;
                num_t denom = d * p(j - 1, i) + e;

                // p[i][j] = -f / denom;
                p(j, i) = -f / denom;

                // Use precomputed base_row(i,j) instead of recomputing
                // the three-point stencil from v each iteration.
                //
                // num =
                //   (-a * v[i-1][j] + (1 + 2*a) * v[i][j] - c * v[i+1][j])
                //   - d * q[i][j-1];
                num_t base_row = row_rhs_buf(j, i); // j == x, i == y
                num_t num      = base_row - d * q(j - 1, i);

                // q[i][j] = num / denom;
                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = one;

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
