using namespace Halide;

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * C array u[i][j] is mapped to Halide Buffer u(j, i).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    Var x("x"), y("y"); // x == j (fast), y == i (slow)
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Schedule: vectorize across x (contiguous dimension) and parallelize across y.
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    init_u
        .compute_root()
        .vectorize(x, vec_width)
        .parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * Optimization strategy:
 *   - The ADI scheme uses a tridiagonal solve along one dimension, which
 *     has a true loop-carried dependency and cannot be expressed as a
 *     legal Halide reduction update (it needs f(x) depending on f(x-1)).
 *   - We keep the Thomas sweeps (forward / backward) in C++ loops, but
 *     extract the *stencil* parts that are pure in space into Halide
 *     Funcs:
 *
 *       Column sweep numerator:
 *         -d * u(i-1, j) + (1 + 2*d) * u(i, j) - f * u(i+1, j)
 *
 *       Row sweep numerator:
 *         -a * v(j, i-1) + (1 + 2*a) * v(j, i) - c * v(j, i+1)
 *
 *   - These stencils are computed over the full interior of the grid
 *     using Halide, with vectorization and parallelization for good
 *     cache behavior and SIMD utilization.
 *   - The scalar recurrences along the tridiagonal direction then use
 *     these precomputed numerators, reducing memory traffic and letting
 *     Halide handle the bandwidth-heavy stencil work.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Scalar parameters (same as original C kernel)
    num_t DX   = num_t(1.0) / num_t(n);
    num_t DY   = num_t(1.0) / num_t(n);
    num_t DT   = num_t(1.0) / num_t(tsteps);
    num_t B1   = num_t(2.0);
    num_t B2   = num_t(1.0);
    num_t mul1 = B1 * DT / (DX * DX);
    num_t mul2 = B2 * DT / (DY * DY);

    num_t a = -mul1 / num_t(2.0);
    num_t b = num_t(1.0) + mul1;
    num_t c = a;
    num_t d = -mul2 / num_t(2.0);
    num_t e = num_t(1.0) + mul2;
    num_t f = d;

    // ------------------------------------------------------------------
    // Halide pipelines for the pure 3-point stencils
    //
    // We precompute, for all interior points, the parts of the numerators
    // that depend only on u (for the column sweep) and only on v (for
    // the row sweep). The loop-carried parts that depend on q are left
    // in C++ to preserve the tridiagonal recurrence semantics.
    // ------------------------------------------------------------------

    Var ii("ii"), jj("jj");

    // Column-sweep stencil:
    //
    //   num = -d * u(i-1, j)
    //         + (1 + 2*d) * u(i, j)
    //         - f * u(i+1, j)
    //
    // Here ii == i (second C index), jj == j (first C index).
    Func rhs_col("rhs_col");
    rhs_col(ii, jj) =
        (-d * u(ii - 1, jj) +
         (num_t(1.0) + num_t(2.0) * d) * u(ii, jj) -
         f * u(ii + 1, jj));

    // Row-sweep stencil:
    //
    //   num = -a * v(j, i-1)
    //         + (1 + 2*a) * v(j, i)
    //         - c * v(j, i+1)
    //
    // Here jj == j, ii == i (consistent with v(j, i±1)).
    Func rhs_row("rhs_row");
    rhs_row(jj, ii) =
        (-a * v(jj, ii - 1) +
         (num_t(1.0) + num_t(2.0) * a) * v(jj, ii) -
         c * v(jj, ii + 1));

    // -------------------------
    // Schedule for the stencils
    // -------------------------
    Target target = get_jit_target_from_environment();
    int vec_width = target.natural_vector_size(type_of<num_t>());
    if (vec_width < 1) {
        vec_width = 1;
    }

    // Column stencil: contiguous dimension is ii (x index into u).
    // Parallelize over jj (the orthogonal direction).
    rhs_col
        .compute_root()
        .vectorize(ii, vec_width)
        .parallel(jj);

    // Row stencil: contiguous dimension is jj (x index into v).
    // Parallelize over ii (the orthogonal direction).
    rhs_row
        .compute_root()
        .vectorize(jj, vec_width)
        .parallel(ii);

    // JIT-compile once; subsequent realize() calls reuse the compiled code.
    rhs_col.compile_jit(target);
    rhs_row.compile_jit(target);

    // Scratch buffers for the stencil results. We only need interior
    // points: 1 .. n-2 in both dimensions. We set the min to 1 so that
    // indices in the original loops (which use [1, n-2]) map directly.
    Halide::Buffer<num_t> rhs_col_buf(n - 2, n - 2);
    rhs_col_buf.set_min(1, 1);

    Halide::Buffer<num_t> rhs_row_buf(n - 2, n - 2);
    rhs_row_buf.set_min(1, 1);

    // Time-stepping loop (still in C++ to respect the 1D recurrences).
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        //   - Precompute the u-based stencil for the whole interior.
        //   - Then perform Thomas forward/backward sweeps per line.
        // ------------------------------------------------------------
        rhs_col.realize(rhs_col_buf);

        for (int i = 1; i < n - 1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = num_t(1.0);

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // p[i][j] = -c / (a * p[i][j-1] + b);
                num_t denom = a * p(j - 1, i) + b;
                p(j, i) = -c / denom;

                // Original:
                //   num = -d * u[i-1][j]
                //         + (1 + 2*d) * u[i][j]
                //         - f * u[i+1][j]
                //         - a * q[i][j-1];
                //
                // We have precomputed the stencil part:
                //   rhs_col(i, j) = -d*u(i-1,j) + (1+2*d)*u(i,j) - f*u(i+1,j)
                //
                // So the full numerator is:
                num_t num = rhs_col_buf(i, j) - a * q(j - 1, i);

                // q[i][j] = num / (a * p[i][j-1] + b);
                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, n - 1) = num_t(1.0);

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        //   - Precompute the v-based stencil for the whole interior.
        //   - Then perform Thomas forward/backward sweeps per line.
        // ------------------------------------------------------------
        rhs_row.realize(rhs_row_buf);

        for (int i = 1; i < n - 1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = num_t(1.0);

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j
            for (int j = 1; j < n - 1; j++) {
                // p[i][j] = -f / (d * p[i][j-1] + e);
                num_t denom = d * p(j - 1, i) + e;
                p(j, i) = -f / denom;

                // Original:
                //   num = -a * v[i-1][j]
                //         + (1 + 2*a) * v[i][j]
                //         - c * v[i+1][j]
                //         - d * q[i][j-1];
                //
                // With mapping to Buffer indices used in this code:
                //   -a * v(j, i-1) + (1 + 2*a) * v(j, i) - c * v(j, i+1)
                //
                // Precomputed as rhs_row(j, i), so:
                num_t num = rhs_row_buf(j, i) - d * q(j - 1, i);

                // q[i][j] = num / (d * p[i][j-1] + e);
                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(n - 1, i) = num_t(1.0);

            // Back substitution along j (descending)
            for (int j = n - 2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
