using num_t = DATA_TYPE;

using namespace Halide;

// Tunable constants for cache-aware blocking. These can be changed
// to better match a given machine's cache hierarchy without touching
// the core algorithm.
constexpr int I_BLOCK = 64;  // tile size along the i-dimension (rows)
constexpr int J_BLOCK = 64;  // tile size along the j-dimension (cols)

/*
 * Initialize array u:
 *
 * Original C:
 *   for (i = 0; i < n; i++)
 *     for (j = 0; j < n; j++)
 *       u[i][j] = (DATA_TYPE)(i + n - j) / n;
 *
 * We store the C array u[i][j] into Halide Buffer u(j, i), i.e.
 *   x = j (fast dimension), y = i (slow dimension).
 */
static void init_array(int n, Halide::Buffer<num_t, 2> u) {
    // x == j (fast), y == i (slow)
    Var x("x"), y("y");
    Func init_u("init_u");

    // u[i][j] = (i + n - j) / n  ==>  u(j, i) = ...
    init_u(x, y) = cast<num_t>(y + n - x) / cast<num_t>(n);

    // Simple but effective schedule:
    //  - vectorize along x (contiguous dimension)
    //  - parallelize along y (independent rows)
    constexpr int VEC_WIDTH = 8;  // reasonable default for modern SIMD
    init_u
        .vectorize(x, VEC_WIDTH)
        .parallel(y);

    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original PolyBench signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i):
 *   - C A[i][j] (row i, col j) is stored in Buffer A(x=j, y=i).
 *
 * Below we implement the original ADI algorithm exactly, but carefully
 * respect the Buffer mapping and organize the loops to maximize data
 * locality:
 *   - Inner loops run over j, which is the fast (x) dimension.
 *   - We use modest blocking over i to keep working sets in cache.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Scalar parameters (identical to PolyBench reference).
    const num_t DX   = num_t(1.0) / num_t(n);
    const num_t DY   = num_t(1.0) / num_t(n);
    const num_t DT   = num_t(1.0) / num_t(tsteps);
    const num_t B1   = num_t(2.0);
    const num_t B2   = num_t(1.0);
    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = num_t(1.0) + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = num_t(1.0) + mul2;
    const num_t f = d;

    // Precompute small constants used in inner loops to avoid
    // recomputing them every iteration.
    const num_t one_plus_2d = num_t(1.0) + num_t(2.0) * d;
    const num_t one_plus_2a = num_t(1.0) + num_t(2.0) * a;

    // Bounds we actually touch (interior points [1, n-2]):
    const int i_start = 1;
    const int i_end   = n - 1;  // loop upper bound is i_end-1 == n-2
    const int j_start = 1;
    const int j_end   = n - 1;  // loop upper bound is j_end-1 == n-2

    // Time-stepping loop (host-driven, as the ADI scheme has
    // loop-carried dependencies that are inherently sequential in t).
    for (int t = 1; t <= tsteps; t++) {

        // ============================================================
        // Column sweep (corresponds to the first big loop nest in C)
        //
        // For each fixed i, we solve a tridiagonal system along j.
        // With our mapping A[i][j] -> A_buf(j, i), we access:
        //   - u(i, j-1), u(i, j), u(i, j+1)
        //   - p(j-1, i), p(j, i), q(j-1, i), q(j, i), v(j, i)
        // All of these have j in the first (x) coordinate, so iterating
        // j in the inner loop yields unit-stride memory access.
        // ============================================================

        // We tile the i-loop to keep a limited number of rows' worth
        // of temporaries in cache. Dependencies are only along j, so
        // tiling i is semantics-preserving.
        for (int i_block = i_start; i_block < i_end; i_block += I_BLOCK) {
            const int i_block_end = std::min(i_block + I_BLOCK, i_end);

            // Initialize column-wise boundary conditions for this tile.
            for (int i = i_block; i < i_block_end; i++) {
                // v[0][i] = 1.0;
                v(i, 0) = num_t(1.0);

                // p[i][0] = 0.0;
                p(0, i) = num_t(0.0);

                // q[i][0] = v[0][i];
                q(0, i) = v(i, 0);
            }

            // Forward sweep along j (Thomas algorithm).
            for (int i = i_block; i < i_block_end; i++) {
                for (int j = j_start; j < j_end; j++) {
                    // Note: p and q are laid out as p(j, i), q(j, i)
                    // so that j is the contiguous (x) dimension.

                    // denom = a * p[i][j-1] + b;
                    const num_t denom = a * p(j - 1, i) + b;

                    // p[i][j] = -c / denom;
                    p(j, i) = -c / denom;

                    // q[i][j] =
                    //   (-d * u[j-1][i]
                    //    + (1 + 2*d) * u[j][i]
                    //    - f * u[j+1][i]
                    //    - a * q[i][j-1]) / denom;
                    const num_t num =
                        -d * u(i, j - 1) +
                        one_plus_2d * u(i, j) -
                        f * u(i, j + 1) -
                        a * q(j - 1, i);

                    q(j, i) = num / denom;
                }
            }

            // Set upper boundary for v in this tile.
            for (int i = i_block; i < i_block_end; i++) {
                // v[n-1][i] = 1.0;
                v(i, n - 1) = num_t(1.0);
            }

            // Backward substitution along j (descending).
            for (int i = i_block; i < i_block_end; i++) {
                for (int j = n - 2; j >= 1; j--) {
                    // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                    v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
                }
            }
        }

        // ============================================================
        // Row sweep (second big loop nest in C)
        //
        // For each fixed i, we again solve a tridiagonal system along j,
        // now using v as the right-hand side and updating u.
        // Memory layout is identical to the column sweep: j is the
        // fast (x) dimension, so we again enjoy unit-stride traversal
        // for all arrays in the inner loop.
        // ============================================================

        for (int i_block = i_start; i_block < i_end; i_block += I_BLOCK) {
            const int i_block_end = std::min(i_block + I_BLOCK, i_end);

            // Initialize row-wise boundary conditions for this tile.
            for (int i = i_block; i < i_block_end; i++) {
                // u[i][0] = 1.0;
                u(0, i) = num_t(1.0);

                // p[i][0] = 0.0;
                p(0, i) = num_t(0.0);

                // q[i][0] = u[i][0];
                q(0, i) = u(0, i);
            }

            // Forward sweep along j.
            for (int i = i_block; i < i_block_end; i++) {
                for (int j = j_start; j < j_end; j++) {
                    // denom = d * p[i][j-1] + e;
                    const num_t denom = d * p(j - 1, i) + e;

                    // p[i][j] = -f / denom;
                    p(j, i) = -f / denom;

                    // q[i][j] =
                    //   (-a * v[i-1][j]
                    //    + (1 + 2*a) * v[i][j]
                    //    - c * v[i+1][j]
                    //    - d * q[i][j-1]) / denom;
                    const num_t num =
                        -a * v(j, i - 1) +
                        one_plus_2a * v(j, i) -
                        c * v(j, i + 1) -
                        d * q(j - 1, i);

                    q(j, i) = num / denom;
                }
            }

            // Set upper boundary for u in this tile.
            for (int i = i_block; i < i_block_end; i++) {
                // u[i][n-1] = 1.0;
                u(n - 1, i) = num_t(1.0);
            }

            // Backward substitution along j (descending).
            for (int i = i_block; i < i_block_end; i++) {
                for (int j = n - 2; j >= 1; j--) {
                    // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                    u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
                }
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major C order.
    // Recall: C u[i][j] == Buffer u(j, i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
