        //   p(j,i) = -c / denom;  q(j,i) = num / denom;
        //   v(i,n-1) = 1.0;
        //   v(i,j)   = p(j,i) * v(i,j+1) + q(j,i);
        // ============================================================

        for (int ii = i_lo; ii < i_hi; ii += TILE_I) {
            const int i_end = std::min(ii + TILE_I, i_hi);

            for (int i = ii; i < i_end; i++) {
