        Expr n_e = cast<int>(n_param);
        init_u(x, y) = cast<num_t>(y + n_e - x) / cast<num_t>(n_e);

        // Simple CPU schedule: vectorize across x (contiguous),
        // parallelize across y (rows).
        Var xo("xo"), xi("xi");
        const int vec_width = 8;  // reasonable default for modern x64
        init_u
            .split(x, xo, xi, vec_width)
            .vectorize(xi)
            .parallel(y);

        // JIT-compile once for the host CPU.
        Target target = get_host_target();
        init_u.compile_jit(target);

        initialized = true;
    }

    // Bind the current problem size and realize directly into 'u'.
    n_param.set(n);
    init_u.realize(u);
}

/*
 * Main computational kernel translated to C++ operating on Halide::Buffer.
 *
 * Original signature:
 *
 *   void kernel_adi(int tsteps, int n,
 *                   DATA_TYPE u[N][N],
 *                   DATA_TYPE v[N][N],
 *                   DATA_TYPE p[N][N],
 *                   DATA_TYPE q[N][N]);
 *
 * Mapping of C indices A[i][j] -> Buffer A(j, i).
 *
 * NOTE:
 *   The ADI kernel contains 1D recurrences (tridiagonal solves)
 *   along the j-dimension. Those loop-carried dependencies cannot
 *   be expressed as legal Halide update definitions (they would
 *   require self-references with shifted indices), so we keep the
 *   core Thomas sweeps as explicit C++ loops, but we:
 *
 *   - Hoist all invariant scalars out of inner loops.
 *   - Precompute frequently used combinations (1 + 2*d, 1 + 2*a).
 *   - Avoid repeated computation of n-1 and n-2.
 *
 *   The data layout A(j, i) already gives good spatial locality for
 *   the innermost j-loops, so we keep that.
 */
static void kernel_adi(int tsteps,
                       int n,
                       Halide::Buffer<num_t, 2> u,
                       Halide::Buffer<num_t, 2> v,
                       Halide::Buffer<num_t, 2> p,
                       Halide::Buffer<num_t, 2> q) {
    // Precompute scalar coefficients once per kernel invocation.
    const num_t one = num_t(1.0);
    const num_t two = num_t(2.0);

    const num_t DX = one / num_t(n);
    const num_t DY = one / num_t(n);
    const num_t DT = one / num_t(tsteps);

    const num_t B1 = num_t(2.0);
    const num_t B2 = num_t(1.0);

    const num_t mul1 = B1 * DT / (DX * DX);
    const num_t mul2 = B2 * DT / (DY * DY);

    const num_t a = -mul1 / num_t(2.0);
    const num_t b = one + mul1;
    const num_t c = a;
    const num_t d = -mul2 / num_t(2.0);
    const num_t e = one + mul2;
    const num_t f = d;

    // Frequently used combinations.
    const num_t one_plus_2d = one + two * d;
    const num_t one_plus_2a = one + two * a;

    // Loop bounds reused often.
    const int nm1 = n - 1;
    const int nm2 = n - 2;

    // Time-stepping loop.
    for (int t = 1; t <= tsteps; t++) {

        // ------------------------------------------------------------
        // Column sweep
        //   For fixed i (row index), we solve a tridiagonal system
        //   along j (column index). Each line is independent of the
        //   others, so the only true recurrences are along j.
        // ------------------------------------------------------------
        for (int i = 1; i < nm1; i++) {
            // v[0][i] = 1.0;
            v(i, 0) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = v[0][i];
            q(0, i) = v(i, 0);

            // Forward sweep along j.
            for (int j = 1; j < nm2; j++) {
                // denom = a * p[i][j-1] + b;
                const num_t pj_prev = p(j - 1, i);
                const num_t denom  = a * pj_prev + b;

                // p[i][j] = -c / denom;
                p(j, i) = -c / denom;

                // q[i][j] =
                //   (-d * u[j][i-1]
                //    + (1 + 2*d) * u[j][i]
                //    - f * u[j][i+1]
                //    - a * q[i][j-1]) /
                //   denom;
                const num_t qj_prev = q(j - 1, i);
                const num_t num =
                    -d * u(i - 1, j) +
                    one_plus_2d * u(i, j) -
                    f * u(i + 1, j) -
                    a * qj_prev;

                q(j, i) = num / denom;
            }

            // v[n-1][i] = 1.0;
            v(i, nm1) = one;

            // Back substitution along j (descending).
            for (int j = nm2; j >= 1; j--) {
                // v[j][i] = p[i][j] * v[j+1][i] + q[i][j];
                v(i, j) = p(j, i) * v(i, j + 1) + q(j, i);
            }
        }

        // ------------------------------------------------------------
        // Row sweep
        //   For fixed i (row index), solve a tridiagonal system along
        //   j (now interpreted as column index of u). Again, each row
        //   is independent and recurrences are along j only.
        // ------------------------------------------------------------
        for (int i = 1; i < nm1; i++) {
            // u[i][0] = 1.0;
            u(0, i) = one;

            // p[i][0] = 0.0;
            p(0, i) = num_t(0.0);

            // q[i][0] = u[i][0];
            q(0, i) = u(0, i);

            // Forward sweep along j.
            for (int j = 1; j < nm2; j++) {
                // denom = d * p[i][j-1] + e;
                const num_t pj_prev = p(j - 1, i);
                const num_t denom  = d * pj_prev + e;

                // p[i][j] = -f / denom;
                p(j, i) = -f / denom;

                // q[i][j] =
                //   (-a * v[i-1][j]
                //    + (1 + 2*a) * v[i][j]
                //    - c * v[i+1][j]
                //    - d * q[i][j-1]) /
                //   denom;
                const num_t qj_prev = q(j - 1, i);
                const num_t num =
                    -a * v(j, i - 1) +
                    one_plus_2a * v(j, i) -
                    c * v(j, i + 1) -
                    d * qj_prev;

                q(j, i) = num / denom;
            }

            // u[i][n-1] = 1.0;
            u(nm1, i) = one;

            // Back substitution along j (descending).
            for (int j = nm2; j >= 1; j--) {
                // u[i][j] = p[i][j] * u[i][j+1] + q[i][j];
                u(j, i) = p(j, i) * u(j + 1, i) + q(j, i);
            }
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem sizes
    int n      = N;
    int tsteps = TSTEPS;

    // Allocate Buffers.
    // C array A[i][j] is mapped as Buffer A(j, i) with shape (n, n).
    Halide::Buffer<num_t, 2> u(n, n);
    Halide::Buffer<num_t, 2> v(n, n);
    Halide::Buffer<num_t, 2> p(n, n);
    Halide::Buffer<num_t, 2> q(n, n);

    // Initialize u; v, p, q are scratch arrays.
    init_array(n, u);

    // Time only the kernel.
    auto start = std::chrono::high_resolution_clock::now();

    kernel_adi(tsteps, n, u, v, p, q);

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally dump the result (u) to stderr, in row-major order.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                // u[i][j] == u_buf(j, i)
                std::cerr << u(j, i) << '\n';
            }
        }
    }

    // Print timing (seconds) to stdout.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
